const FREE_SHIPPING_OVER_CENTS = 5000
const DOMESTIC_RATE_CENTS = 599
const INTERNATIONAL_RATE_CENTS = 1500

function shippingCents(order: Order): number {
  if (!order) throw new Error('no order')
  if (order.items.length === 0) throw new Error('empty order')
  if (order.country !== 'US') return INTERNATIONAL_RATE_CENTS
  return order.totalCents > FREE_SHIPPING_OVER_CENTS ? 0 : DOMESTIC_RATE_CENTS
}

