const NEW_CUSTOMER_WINDOW_MS = 30 * 24 * 60 * 60 * 1000
const NEW_CUSTOMER_DISCOUNT = 0.1

export function discountedTotalCents(totalCents: number, createdAt: number, now: number): number {
  const isNewCustomer = now - createdAt < NEW_CUSTOMER_WINDOW_MS
  return isNewCustomer ? Math.round(totalCents * (1 - NEW_CUSTOMER_DISCOUNT)) : totalCents
}

export async function applyNewCustomerDiscount(userId: string, now = Date.now()) {
  const user = await db.users.find(userId)
  const totalCents = discountedTotalCents(user.cart.totalCents, user.createdAt, now)
  await db.users.save({ ...user, cart: { ...user.cart, totalCents } })
}

