interface Notifier {
  orderPlaced(orderId: string): Promise<void>
}

class OrderService {
  constructor(private orders: OrderRepository, private notifier: Notifier) {}

  async place(order: Order): Promise<void> {
    await this.orders.save(order)
    await this.notifier.orderPlaced(order.id)
  }
}

